//! One test per expectation of every scenario, generated by `build.rs`.
//!
//! A `met` expectation's test runs; a `target`'s is ignored with a
//! `TODO: fine tune to catch this` reason, and `cargo test -p corpus --
//! --ignored` lists every target the engine does not meet yet.
//! `no_target_passes_unpromoted` fails as soon as a target holds, so a
//! closed gap is promoted in the pull request that closes it.

use corpus::expect::Finding;

fn well_formed(scenario: &str) {
    match corpus::malformations(scenario) {
        Ok(problems) => assert!(
            problems.is_empty(),
            "{scenario} is malformed:\n  {}",
            problems.join("\n  ")
        ),
        Err(e) => panic!("{scenario}: {e}"),
    }
}

fn no_unpromoted_target(scenario: &str) {
    match corpus::unpromoted_targets(scenario) {
        Ok(holding) => assert!(
            holding.is_empty(),
            "{scenario}: these targets hold now; promote them to `met`: {}",
            holding.join(", ")
        ),
        Err(e) => panic!("{scenario}: {e}"),
    }
}

fn holds(scenario: &str, expectation: &str) {
    match corpus::evaluate(scenario, expectation) {
        Ok(Finding::Holds { .. }) => {}
        Ok(other) => panic!("{scenario}/{expectation}: {}", other.describe()),
        Err(e) => panic!("{scenario}/{expectation}: {e}"),
    }
}

include!(concat!(env!("OUT_DIR"), "/scenario_tests.rs"));
